builder.Services.AddRateLimiter(o => { o.RejectionStatusCode = StatusCodes.Status429TooManyRequests; o.AddTokenBucketLimiter("api", b => { b.TokenLimit = 100; b.TokensPerPeriod = 50; b.ReplenishmentPeriod = TimeSpan.FromSeconds(1); b.QueueLimit = 0; }); });
app.UseRateLimiter();
app.MapGet("/orders", GetOrders).RequireRateLimiting("api");

o.GlobalLimiter = PartitionedRateLimiter.Create<HttpContext, string>(ctx =>
    RateLimitPartition.GetTokenBucketLimiter(ctx.Request.Headers["X-Api-Key"].ToString(), _ =>
        new TokenBucketRateLimiterOptions { TokenLimit = 20, TokensPerPeriod = 10, ReplenishmentPeriod = TimeSpan.FromSeconds(1), QueueLimit = 0 }));

var pipeline = new ResiliencePipelineBuilder()
    .AddRetry(new RetryStrategyOptions { MaxRetryAttempts = 2, BackoffType = DelayBackoffType.Exponential, UseJitter = true, Delay = TimeSpan.FromMilliseconds(100) })
    .AddCircuitBreaker(new CircuitBreakerStrategyOptions { FailureRatio = 0.5, SamplingDuration = TimeSpan.FromSeconds(30), MinimumThroughput = 20, BreakDuration = TimeSpan.FromSeconds(15) })
    .AddTimeout(TimeSpan.FromMilliseconds(300))
    .Build();
await pipeline.ExecuteAsync(async ct => await db.QueryAsync(ct), cancellationToken);
